export const scenarios={agency:'Somos una agencia de diseño. Recibimos consultas desde un formulario y las copiamos a una hoja. Queremos registrar cada solicitud y preparar una respuesta. Nos llegan unas 20 por semana.',training:'Organizamos cursos para empresas. Necesitamos registrar las consultas sobre fechas y plazas, preparar una respuesta y revisar qué personas siguen pendientes.',software:'Somos un estudio de desarrollo de software. Queremos ordenar los reportes de errores que llegan por formulario, registrar navegador y pasos para reproducirlos, y preparar una respuesta para revisar.',documents:'Somos una asesoría. Queremos registrar solicitudes de extracción de datos de documentos PDF y facturas, comprobar los campos necesarios y organizar una revisión antes de pasar los datos a Excel.',commerce:'Tenemos una tienda online. Queremos ordenar las solicitudes sobre pedidos y devoluciones que llegan por correo, preparar un borrador y asignar el siguiente paso.',incomplete:'Hola, quisiera información sobre vuestros servicios.'};
export function fingerprint(text){return text.normalize('NFKC').toLowerCase().replace(/\s+/g,' ').trim()}
export function addRequest(records,text){text=String(text).trim();if(text.length<20||text.length>1500)throw new Error('Describe la solicitud con entre 20 y 1.500 caracteres.');const key=fingerprint(text);const duplicate=records.find(r=>r.key===key);if(duplicate)return {records,record:duplicate,duplicate:true};const incomplete=text.length<90;const topic=/software|errores|navegador/i.test(text)?'Consulta de software':/documentos|pdf|facturas/i.test(text)?'Consulta de documentos':/devoluc|pedidos|tienda/i.test(text)?'Consulta de comercio':/\bcursos?\b|\bplazas?\b|\bformaci[oó]n\b/i.test(text)?'Consulta de formación':/agencia|diseño/i.test(text)?'Consulta de agencia':'Solicitud de información';const question=incomplete?'¿Qué tarea quieres organizar y qué herramientas utilizas actualmente?':'¿Qué herramientas utilizáis y qué información debe tener cada registro?';const record={id:records.length+1,key,topic,text,status:incomplete?'Faltan datos':'Pendiente de revisión',nextAction:incomplete?'Pedir información antes de presupuestar':'Confirmar herramientas, campos y volumen',draft:`Hola, gracias por contarnos lo que necesitáis. ${question} Con esa información podremos revisar el alcance y preparar una propuesta. Este mensaje no confirma un presupuesto ni una fecha de entrega.`};return {records:[...records,record],record,duplicate:false}}
export function prepareBrief({company,task,tools,volume,budget}){if(!company?.trim()||!tools?.trim()||task?.trim().length<20)throw new Error('Completa la actividad, las herramientas y una descripción de al menos 20 caracteres.');return `Consulta de automatización\n\nActividad: ${company.trim()}\nProceso y resultado deseado: ${task.trim()}\nHerramientas actuales: ${tools.trim()}\nVolumen: ${volume?.trim()||'Por confirmar'}\nPresupuesto orientativo: ${budget||'Por definir'}\n\nMe gustaría recibir una propuesta con alcance, precio y posibles costes de herramientas.\nPreferencia: comunicación por escrito.\n\nBORRADOR: esta consulta no se ha enviado.`}

// Quote CSV fields and neutralise spreadsheet formula prefixes in user-supplied text.
export function recordsToCsv(records){
 const cell=value=>{let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};
 const rows=[['ID','Tipo','Solicitud','Estado','Próxima acción','Borrador'],...records.map(r=>[r.id,r.topic,r.text,r.status,r.nextAction,r.draft])];
 return '\uFEFF'+rows.map(row=>row.map(cell).join(';')).join('\r\n');
}

export const contactEmail='nexotopo@outlook.com';
export function enquiryLinks(brief){
 const body=String(brief).trim();if(!body||body.length>5000)throw new Error('Prepara una consulta de hasta 5.000 caracteres.');
 const subject='Consulta de proyecto · Nexotopo';
 return {mailto:`mailto:${contactEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`,outlook:`https://outlook.live.com/mail/0/deeplink/compose?to=${encodeURIComponent(contactEmail)}&subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`};
}
